-- Category crosswalk (Nov 13, 2026). Generated by scripts/build-category-crosswalk.mjs
-- Historical time_entries are not rewritten. Views expose mapped names.

CREATE TABLE IF NOT EXISTS public.activity_types (
  activity_type_id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  billable_type text NOT NULL,
  exists_in_memtime boolean NOT NULL DEFAULT false,
  is_new_type boolean NOT NULL DEFAULT false,
  activity_group text,
  description text,
  sort_order integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.department_map (
  old_department_id text PRIMARY KEY,
  old_department text NOT NULL,
  old_department_memtime_name text NOT NULL,
  new_department_id text NOT NULL,
  new_department text NOT NULL,
  live_name_verified boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS public.role_map (
  old_role_id text PRIMARY KEY,
  old_department text NOT NULL,
  old_role text NOT NULL,
  new_department text NOT NULL,
  new_role text NOT NULL,
  new_role_verified_live boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS public.task_map (
  row_id text PRIMARY KEY,
  old_department text NOT NULL,
  old_department_memtime_name text NOT NULL,
  old_role text,
  old_task text NOT NULL,
  old_task_normalized text NOT NULL,
  new_department text NOT NULL,
  new_role text NOT NULL,
  new_activity_type_id text NOT NULL REFERENCES public.activity_types (activity_type_id),
  new_activity_type text NOT NULL,
  billable_type text NOT NULL,
  historical_billable_rule text NOT NULL
);

TRUNCATE public.task_map, public.role_map, public.department_map, public.activity_types;














CREATE INDEX IF NOT EXISTS task_map_lookup_idx
  ON public.task_map (old_department, old_role, old_task);
CREATE INDEX IF NOT EXISTS task_map_memtime_lookup_idx
  ON public.task_map (old_department_memtime_name, old_role, old_task);

-- Original department/role/task/type stay as logged. Mapped columns are for reporting.
CREATE OR REPLACE VIEW public.v_time_entries_clean AS
SELECT
  te.id,
  te.person,
  te.date,
  te.department,
  te."role" AS role,
  te.task,
  te."type" AS type,
  te.billable,
  te.hours,
  te.comments,
  te.created_at,
  te.source_file,
  te.source_month,
  te.source_row_number,
  te.source_status,
  te.source_time_range,
  (te.billable = 'Billable') AS is_billable,
  to_char(te.date, 'YYYY-MM') AS year_month,
  date_trunc('month', te.date::timestamp)::date AS month_start,
  COALESCE(e.active, true) AS employee_active,
  (NULLIF(btrim(te.comments), '') IS NOT NULL) AS has_comments,
  CASE WHEN new_shape.ok THEN te.department ELSE COALESCE(tm.new_department, te.department) END AS mapped_department,
  CASE WHEN new_shape.ok THEN te."role" ELSE COALESCE(tm.new_role, te."role") END AS mapped_role,
  CASE WHEN new_shape.ok THEN te."type" ELSE COALESCE(tm.new_activity_type, te."type") END AS mapped_activity_type
FROM public.time_entries te
LEFT JOIN public.employees e ON e.person = te.person
LEFT JOIN LATERAL (
  SELECT (
    te.department IS NOT NULL
    AND te.department NOT LIKE '% (old)'
    AND te."type" IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.activity_types a WHERE a.name = te."type")
    AND EXISTS (SELECT 1 FROM public.department_map d WHERE d.new_department = te.department)
    AND NOT EXISTS (
      SELECT 1 FROM public.department_map d
      WHERE d.old_department = te.department AND d.old_department <> d.new_department
    )
  ) AS ok
) new_shape ON true
LEFT JOIN LATERAL (
  SELECT t.new_department, t.new_role, t.new_activity_type
  FROM public.task_map t
  WHERE (
      t.old_department = te.department
      OR t.old_department_memtime_name = te.department
    )
    AND t.old_role IS NOT DISTINCT FROM NULLIF(btrim(te."role"), '')
    AND (
      t.old_task = te.task
      OR (t.old_task <> t.old_task_normalized AND t.old_task_normalized = te.task)
    )
  ORDER BY CASE WHEN t.old_task = te.task THEN 0 ELSE 1 END, t.row_id
  LIMIT 1
) tm ON true;

GRANT SELECT ON public.activity_types, public.department_map, public.role_map, public.task_map TO anon, authenticated, service_role;
GRANT SELECT ON public.v_time_entries_clean TO anon, authenticated, service_role;